#!/bin/bash
# ============================================================================
# optometry_refraction_dx_prescription_updates.sh
#
# Four independent minor changes, bundled into one deploy:
#
# 1. PG (Present Glasses) Power table -- removed the VA column. It never
#    made sense there (VA belongs to actual vision testing, not a reading
#    off a lensometer of glasses the patient already owns).
#
# 2. Refraction (Objective/Subjective/Final Rx) -- added an ADD row
#    beneath Dist. ADD (near addition power) is always positive; Near
#    SPH/CYL/AXIS are now auto-computed and read-only:
#      Near SPH  = Dist SPH + ADD (algebraic sum)
#      Near CYL  = same as Dist CYL
#      Near AXIS = same as Dist AXIS
#      Near VA stays independently entered -- untouched by this logic.
#    Works per refraction type (Obj/Subj/Final) and per eye, respects
#    "Copy RE to LE", and is included in "Copy from Subjective/Objective"
#    into Final Rx. Final Rx's ADD is also now shown on the printed
#    glasses prescription.
#
#    DATABASE: ref_obj_re_add / ref_obj_le_add / ref_subj_re_add /
#    ref_subj_le_add columns were ALREADY ADDED to both Supabase projects
#    (production flzysyzhaecaqbmdcuao and training ffaddzpwnbizhvhujlse)
#    via migration -- ref_final_re_add/ref_final_le_add already existed.
#    No SQL needs to run from this script.
#
# 3. Diagnosis -- Posterior Segment C:D ratio dropdown now includes
#    0.65, 0.75, 0.85, 0.95 alongside the existing 0.1-0.9 steps.
#
# 4. Prescription (Treatment tab) and Discharge (Post-op Medication)
#    modules:
#      - Tablets/capsules/syrups/injections (non-ocular drugs) now show
#        "Oral" instead of a blank where Eye used to be -- covers the
#        main list, tapering-schedule display, and the "quick add from
#        last visit" buttons.
#      - Duration dropdown (main + tapering-schedule builder, in both
#        modules) now also offers 1/2/4/5 days, 10 days, and 2/3/4/5/6
#        months, alongside the existing 3 days/1 week/2 weeks/1 month/
#        Ongoing.
#
#   MODIFIED: app/(main)/optometry/[id]/optometry-workspace.js
#   MODIFIED: app/(main)/optometry/actions.js
#   MODIFIED: app/consultation/[id]/examination-tab.js
#   MODIFIED: app/consultation/[id]/consultation-form.js
#   MODIFIED: app/(main)/ot-recovery/workspace.js
#   MODIFIED: app/print-templates/actions.js
#
# Run this from the root of your veda-hmis repo in GitHub Codespaces.
# ============================================================================

set -e

echo "==> Optometry / Refraction / Diagnosis / Prescription updates"
echo ""

if [ ! -f "package.json" ] || [ ! -d "app" ]; then
  echo "ERROR: This doesn't look like the veda-hmis repo root (no package.json / app dir found)."
  echo "cd into your repo root and re-run this script."
  exit 1
fi

echo "==> Overwriting app/(main)/optometry/[id]/optometry-workspace.js"
echo "" | base64 -d > "app/(main)/optometry/[id]/optometry-workspace.js"

echo "==> Overwriting app/(main)/optometry/actions.js"
echo "" | base64 -d > "app/(main)/optometry/actions.js"

echo "==> Overwriting app/consultation/[id]/examination-tab.js"
echo "" | base64 -d > "app/consultation/[id]/examination-tab.js"

echo "==> Overwriting app/consultation/[id]/consultation-form.js"
echo "" | base64 -d > "app/consultation/[id]/consultation-form.js"

echo "==> Overwriting app/(main)/ot-recovery/workspace.js"
echo "" | base64 -d > "app/(main)/ot-recovery/workspace.js"

echo "==> Overwriting app/print-templates/actions.js"
echo "" | base64 -d > "app/print-templates/actions.js"

echo ""
echo "==> Files written. Verifying build..."
if command -v npm >/dev/null 2>&1; then
  npm run build || { echo "BUILD FAILED -- check output above before pushing."; exit 1; }
else
  echo "npm not found -- skipping build verification, run 'npm run build' manually."
fi

echo ""
echo "==> Done. Review changes with: git status && git diff"
echo "==> To deploy, run:"
echo "    git add -A"
echo '    git commit -m "Optometry: remove PG VA column, add ADD/auto-Near refraction, CDR values, Oral label + more durations"'
echo "    git push"
